import copy, json
_FIELDS = ("payload", "done", "token", "until", "attempts", "dead")
def _live(row, now):
    return row["token"] is not None and (row["until"] is None or now < row["until"])
def _int(value):
    return isinstance(value, int) and not isinstance(value, bool)
class Queue:
    def __init__(self, max_attempts=3):
        if not _int(max_attempts) or max_attempts <= 0: raise ValueError("max_attempts must be a positive integer")
        self.items = {}; self.serial = 0; self.max_attempts = max_attempts; self.seen = {}
    def enqueue(self, key, payload):
        if key not in self.items:
            self.items[key] = {"payload": payload, "done": False, "token": None, "until": None, "attempts": 0, "dead": False}
    def claim(self, key, now=0, ttl=10):
        if not _int(now) or now < 0: raise ValueError("now must be an integer >= 0")
        if not _int(ttl) or ttl <= 0: raise ValueError("ttl must be a positive integer")
        row = self.items.get(key)
        if row is None or row["done"] or row["dead"]: return None
        if row["token"] is not None:
            if _live(row, now): return None
            row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts:
            row["dead"] = True; return None
        self.serial += 1; row["token"] = self.serial; row["until"] = now + ttl; row["attempts"] += 1
        return row["payload"], self.serial
    def dead(self, key):
        row = self.items.get(key)
        return bool(row and row["dead"])
    def batch(self, keys, now=0, ttl=10):
        if not _int(now) or now < 0: raise ValueError("now must be an integer >= 0")
        if not _int(ttl) or ttl <= 0: raise ValueError("ttl must be a positive integer")
        if not isinstance(keys, list) or any(not isinstance(k, str) for k in keys) or len(set(keys)) != len(keys):
            raise ValueError("keys must be a list of unique strings")
        for key in keys:
            row = self.items.get(key)
            if row is None or row["done"] or row["dead"]: return None
            if _live(row, now): return None
            if row["attempts"] >= self.max_attempts: return None
        return {key: self.claim(key, now, ttl) for key in keys}
    def ack(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["token"] is None or row["token"] != token: return False
        row["done"] = True; return True
    def retry(self, key, token):
        row = self.items.get(key)
        if not row or row["done"] or row["dead"] or row["token"] is None or row["token"] != token: return False
        row["token"] = None; row["until"] = None
        if row["attempts"] >= self.max_attempts: row["dead"] = True
        return True
    def dumps(self):
        return json.dumps({"version": 2, "serial": self.serial, "max_attempts": self.max_attempts,
                           "items": {k: {f: row[f] for f in _FIELDS} for k, row in self.items.items()},
                           "seen": self.seen})
    @classmethod
    def loads(cls, text):
        try: data = json.loads(text)
        except (TypeError, ValueError) as exc: raise ValueError("malformed JSON") from exc
        version = data.get("version") if isinstance(data, dict) else None
        if isinstance(version, bool) or version not in (1, 2): raise ValueError("unsupported snapshot")
        if version == 1: return cls._from_v1(data)
        for f in ("serial", "max_attempts", "items", "seen"):
            if f not in data: raise ValueError("missing field " + f)
        if not _int(data["serial"]) or data["serial"] < 0: raise ValueError("bad serial")
        if not isinstance(data["items"], dict) or not isinstance(data["seen"], dict): raise ValueError("bad snapshot")
        q = cls(data["max_attempts"]); q.serial = data["serial"]; q.seen = dict(data["seen"])
        for key, row in data["items"].items():
            if not isinstance(row, dict) or any(f not in row for f in _FIELDS): raise ValueError("bad item " + key)
            if not _int(row["attempts"]) or row["attempts"] < 0: raise ValueError("bad attempts")
            if row["token"] is not None and (not _int(row["token"]) or row["token"] > q.serial): raise ValueError("bad token")
            if row["until"] is not None and not _int(row["until"]): raise ValueError("bad until")
            q.items[key] = {f: row[f] for f in _FIELDS}
        return q
    @classmethod
    def _from_v1(cls, data):
        for f in ("serial", "items"):
            if f not in data: raise ValueError("missing field " + f)
        if not _int(data["serial"]) or data["serial"] < 0 or not isinstance(data["items"], dict): raise ValueError("bad snapshot")
        q = cls(); q.serial = data["serial"]
        for key, row in data["items"].items():
            if not isinstance(row, dict) or any(f not in row for f in ("payload", "done", "token")): raise ValueError("bad item " + key)
            token = row["token"]
            if token is not None and (not _int(token) or token > q.serial): raise ValueError("bad token")
            q.items[key] = {"payload": row["payload"], "done": bool(row["done"]), "token": token, "until": None,
                            "attempts": 0 if token is None else 1, "dead": False}
        return q
    def replay(self, events):
        if not isinstance(events, list): raise ValueError("events must be a list")
        backup = copy.deepcopy((self.items, self.serial, self.seen))
        try:
            results = [self._apply(e) for e in events]
        except Exception as exc:
            self.items, self.serial, self.seen = backup
            if isinstance(exc, ValueError): raise
            raise ValueError("invalid event") from exc
        return results
    def _apply(self, event):
        if not isinstance(event, dict) or set(event) != {"event", "op", "args"}: raise ValueError("bad event")
        eid, op, args = event["event"], event["op"], event["args"]
        if not isinstance(eid, str) or op not in ("enqueue", "claim", "ack", "retry") or not isinstance(args, list):
            raise ValueError("bad event")
        try: ident = json.loads(json.dumps([op, args]))
        except (TypeError, ValueError) as exc: raise ValueError("unserializable event") from exc
        if eid in self.seen:
            if self.seen[eid] != ident: raise ValueError("conflicting event " + eid)
            return None
        if not args or not isinstance(args[0], str): raise ValueError("bad event key")
        try: result = getattr(self, op)(*args)
        except TypeError as exc: raise ValueError("bad event args") from exc
        self.seen[eid] = ident
        return result
